{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "config": {
    "kibana": {
      "hideWarnings": true
    }
  },
  "data": [
    {
      "format": {
        "property": "aggregations.lv.buckets"
      },
      "name": "lv",
      "transform": [
        {
          "as": [
            "ord"
          ],
          "ops": [
            "row_number"
          ],
          "type": "window"
        },
        {
          "as": "num",
          "expr": "format(datum.doc_count, ',')",
          "type": "formula"
        },
        {
          "as": "label",
          "expr": "datum.ord == 1 ? 'All alerts' : (datum.ord == 2 ? 'Level 7-11' : 'Level 12+')",
          "type": "formula"
        },
        {
          "as": "colour",
          "expr": "datum.ord == 1 ? '#1f5bb0' : (datum.doc_count == 0 ? '#2e7d32' : (datum.ord == 2 ? '#b26a00' : '#c62828'))",
          "type": "formula"
        }
      ],
      "url": {
        "body": {
          "aggs": {
            "lv": {
              "filters": {
                "filters": [
                  {
                    "match_all": {}
                  },
                  {
                    "range": {
                      "rule.level": {
                        "gte": 7,
                        "lte": 11
                      }
                    }
                  },
                  {
                    "range": {
                      "rule.level": {
                        "gte": 12
                      }
                    }
                  }
                ]
              }
            }
          },
          "query": {
            "bool": {
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "query_string": {
                    "analyze_wildcard": true,
                    "query": "rule.id:[133500 TO 133599] AND rule.id:/[0-9]{6}/"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "size": 0
        },
        "index": "wazuh-alerts-*"
      }
    }
  ],
  "marks": [
    {
      "encode": {
        "enter": {
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "bottom"
          },
          "cursor": {
            "value": "pointer"
          },
          "dy": {
            "value": -4
          },
          "fill": {
            "field": "colour"
          },
          "fontSize": {
            "value": 34
          },
          "fontWeight": {
            "value": "bold"
          },
          "text": {
            "field": "num"
          },
          "tooltip": {
            "value": "Click to filter the dashboard"
          },
          "x": {
            "band": 0.5,
            "field": "ord",
            "scale": "x"
          },
          "y": {
            "signal": "height / 2"
          }
        },
        "hover": {
          "opacity": {
            "value": 0.75
          }
        },
        "update": {
          "opacity": {
            "value": 1
          }
        }
      },
      "from": {
        "data": "lv"
      },
      "name": "num",
      "type": "text"
    },
    {
      "encode": {
        "enter": {
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "top"
          },
          "cursor": {
            "value": "pointer"
          },
          "dy": {
            "value": 6
          },
          "fill": {
            "value": "#3d444d"
          },
          "fontSize": {
            "value": 13
          },
          "text": {
            "field": "label"
          },
          "x": {
            "band": 0.5,
            "field": "ord",
            "scale": "x"
          },
          "y": {
            "signal": "height / 2"
          }
        }
      },
      "from": {
        "data": "lv"
      },
      "name": "lbl",
      "type": "text"
    }
  ],
  "scales": [
    {
      "domain": {
        "data": "lv",
        "field": "ord"
      },
      "name": "x",
      "padding": 0.05,
      "range": "width",
      "type": "band"
    }
  ],
  "signals": [
    {
      "name": "jtFilter",
      "on": [
        {
          "events": "@num:click, @lbl:click",
          "update": "datum.ord == 1 ? opensearchDashboardsAddFilter({\"query_string\": {\"analyze_wildcard\": true, \"query\": \"rule.id:[133500 TO 133599] AND rule.id:/[0-9]{6}/\"}}, \"wazuh-alerts-*\", \"jt-modsecurity rules\") : datum.ord == 2 ? opensearchDashboardsAddFilter({\"range\": {\"rule.level\": {\"gte\": 7, \"lte\": 11}}}, \"wazuh-alerts-*\", \"Level 7-11\") : datum.ord == 3 ? opensearchDashboardsAddFilter({\"range\": {\"rule.level\": {\"gte\": 12}}}, \"wazuh-alerts-*\", \"Level 12+\") : null"
        }
      ],
      "value": null
    }
  ]
}"},"title":"jt-modsecurity · Alerts","type":"vega"}

